import os
import requests
from zipfile import ZipFile, BadZipFile
def task_func(url, download_path="mnt/data/downloads/"):
    try:
        # Ensure download directory exists
        os.makedirs(download_path, exist_ok=True)

        # Download the file
        try:
            response = requests.get(url, stream=True, timeout=30)
            response.raise_for_status()
        except Exception:
            return "Error: Unable to download the file from the provided URL."

        # Check content type
        content_type = response.headers.get('content-type', '').lower()
        if 'application/zip' not in content_type and 'application/octet-stream' not in content_type:
            # Try to check if it's actually a zip by looking at the first bytes
            # But for strict checking, we'll use content-type first
            if not content_type.startswith('application/'):
                return "Error: The URL does not point to a ZIP file."

        # Save the downloaded content to a temporary file
        zip_path = os.path.join(download_path, 'temp_download.zip')
        with open(zip_path, 'wb') as f:
            for chunk in response.iter_content(chunk_size=8192):
                if chunk:
                    f.write(chunk)

        # Try to extract the zip file
        try:
            with ZipFile(zip_path, 'r') as zip_ref:
                zip_ref.extractall(download_path)
        except BadZipFile:
            # Clean up the invalid zip file
            if os.path.exists(zip_path):
                os.remove(zip_path)
            return "Error: The downloaded file is not a valid ZIP file."
        except Exception:
            if os.path.exists(zip_path):
                os.remove(zip_path)
            return "Error: The downloaded file is not a valid ZIP file."

        # Clean up the temporary zip file
        if os.path.exists(zip_path):
            os.remove(zip_path)

        return download_path

    except Exception as e:
        return f"Error: {str(e)}"

