    url_pattern = r'https?://[^\s<>"\'(){}|\\^`\[\]]+'
    urls = re.findall(url_pattern, myString)

    # Extract unique domains from URLs
    domains = set()
    for url in urls:
        try:
            parsed = urllib.parse.urlparse(url)
            domain = parsed.netloc
            # Remove port number if present
            if ':' in domain:
                domain = domain.split(':')[0]
            if domain:
                domains.add(domain)
        except Exception:
            continue

    # Get geolocation data for each domain
    result = {}
    for domain in domains:
        try:
            # Use ip-api.com (free tier, no API key required for basic usage)
            # If you have a different API, modify the URL accordingly
            response = requests.get(f'http://ip-api.com/json/{domain}?fields=status,country,region,city,lat,lon,isp,org,as,query', timeout=10)

            if response.status_code == 200:
                data = response.json()
                if data.get('status') == 'success':
                    result[domain] = data
                else:
                    result[domain] = None
            else:
                result[domain] = None
        except requests.exceptions.RequestException:
            result[domain] = None
        except Exception:
            result[domain] = None

    return result

